	if (!serviceTier) return false;
	if (provider === "openai" || provider === "openai-codex" || provider === "openrouter") {
		return serviceTier === "flex" || serviceTier === "scale" || serviceTier === "priority";
	}
	if (provider === "google") {
		return serviceTier === "flex" || serviceTier === "priority";
	}
